SELECT CASE WHEN status IN ('SUCCESS', 'FAILED') THEN 'group_a' ELSE 'other' END status_group, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) failed_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(method))) method_values FROM payments WHERE order_id IN (13, 35) AND TO_DATE(paid_at) >= '2024-04-01' AND amount < 670 GROUP BY 1 HAVING COUNT(CASE WHEN status = 'FAILED' THEN 1 END) > 5 ORDER BY method_values;
